config.code:
const bankTxns = input.bankTransactions;
const internalPayments = input.internalPayments;
const matched = [];
const unmatched_bank = [];
const unmatched_internal = [];
const amount_mismatches = [];

const internalMap = new Map(internalPayments.map(p => [p.gateway_reference, p]));

for (const txn of bankTxns) {
  const internal = internalMap.get(txn.reference);
  if (!internal) {
    unmatched_bank.push(txn);
  } else if (Math.abs(parseFloat(txn.amount) - parseFloat(internal.amount)) > 0.01) {
    amount_mismatches.push({ bank: txn, internal });
    internalMap.delete(txn.reference);
  } else {
    matched.push({ bank: txn, internal });
    internalMap.delete(txn.reference);
  }
}

for (const [ref, payment] of internalMap) {
  unmatched_internal.push(payment);
}

return { matched, unmatched_bank, unmatched_internal, amount_mismatches, summary: { totalBank: bankTxns.length, totalInternal: internalPayments.length, matchedCount: matched.length, discrepancies: unmatched_bank.length + unmatched_internal.length + amount_mismatches.length } };

